//! instead of signing in. Not in Rails Campfire: a bot is a `users` row with the `bot` role (so it
//! joins rooms and authors messages like anyone), plus a row in this app's own `bots` table (see
//! `schema::ADDITIONS`) with who created it and the token its key carries.

use rusqlite::{Connection, params};

use crate::database::Tx;
use crate::error::{Errors, OptionalExt, Result};
use crate::models::user::user_columns;
use crate::models::{NewUser, PasswordDigest, Role, User, UserChanges};
use crate::sql::{self, CachedStatements, columns, query_all, query_one};
use crate::time::Timestamp;

/// How many characters of `SecureRandom.alphanumeric` a token has: about 143 bits.
pub const TOKEN_LENGTH: usize = 24;

#[derive(Debug, Clone, PartialEq)]
pub struct Bot {
    pub id: i64,
    /// The bot's own `users` row.
    pub user_id: i64,
    /// Who set the bot up: they (and administrators) can see its key, edit and delete it.
    pub creator_id: i64,
    pub token: String,
    pub created_at: Timestamp,
    pub updated_at: Timestamp,
}

/// Attributes for [`Bot::create`].
#[derive(Debug, Clone)]
pub struct NewBot {
    pub name: String,
    pub creator_id: i64,
    /// A bot never signs in, but `users.password_digest` is `NOT NULL` and Rails'
    /// `has_secure_password` wants one present: the digest of a random password nobody knows.
    pub password_digest: PasswordDigest,
}

columns! {
    Bot, "bots", bot_columns {
        id: "id",
        user_id: "user_id",
        creator_id: "creator_id",
        token: "token",
        created_at: "created_at",
        updated_at: "updated_at",
    }
}

/// The active bot users and their `bots` rows, joined (`User::SELECT`'s columns first).
const SELECT_ACTIVE: &str = concat!(
    "SELECT ",
    user_columns!(),
    ", ",
    bot_columns!(),
    r#" FROM "users" INNER JOIN "bots" ON "bots"."user_id" = "users"."id" WHERE "users"."status" = 0 AND "users"."role" = 2"#
);

impl Bot {
    fn user_and_bot(row: &rusqlite::Row<'_>) -> rusqlite::Result<(User, Bot)> {
        Ok((User::from_row(row)?, Bot::from_row_at(row, User::COLUMNS.len())?))
    }

    // Finders

    /// The `bots` row of a bot's user, whatever the user's status.
    pub fn find_by_user_id(conn: &Connection, user_id: i64) -> Result<Option<Self>> {
        query_one(conn, concat!("SELECT ", bot_columns!(), r#" FROM "bots" WHERE "bots"."user_id" = ? LIMIT 1"#), [user_id], Self::from_row)
    }

    /// The active bots `user` may manage, by name: everyone's for an administrator, otherwise the
    /// ones they created.
    pub fn manageable_by(conn: &Connection, user: &User) -> Result<Vec<(User, Bot)>> {
        if user.is_administrator() {
            query_all(conn, &format!("{SELECT_ACTIVE} ORDER BY LOWER(\"users\".\"name\")"), [], Self::user_and_bot)
        } else {
            let sql = format!(r#"{SELECT_ACTIVE} AND "bots"."creator_id" = ? ORDER BY LOWER("users"."name")"#);
            query_all(conn, &sql, [user.id], Self::user_and_bot)
        }
    }

    /// One of [`Bot::manageable_by`], by the bot's user id; `RecordNotFound` for anyone else's.
    pub fn find_manageable_by(conn: &Connection, user: &User, bot_user_id: i64) -> Result<(User, Bot)> {
        let found = query_one(conn, &format!(r#"{SELECT_ACTIVE} AND "users"."id" = ? LIMIT 1"#), [bot_user_id], Self::user_and_bot)?;
        found.filter(|(_, bot)| user.can_administer(Some(bot.creator_id), false)).or_not_found("User")
    }

    /// The active bot a bot key (`"<user id>-<token>"`, see [`Bot::key`]) belongs to. The token is
    /// compared in constant time, so a response's timing doesn't reveal how much of it matched.
    pub fn authenticate(conn: &Connection, key: &str) -> Result<Option<User>> {
        let Some((id, token)) = key.split_once('-') else { return Ok(None) };
        let Some(id) = id.parse::<i64>().ok().filter(|_| id.bytes().all(|b| b.is_ascii_digit())) else { return Ok(None) };
        let found = query_one(conn, &format!(r#"{SELECT_ACTIVE} AND "users"."id" = ? LIMIT 1"#), [id], Self::user_and_bot)?;
        Ok(found.filter(|(_, bot)| rails_compat::secure_compare(bot.token.as_bytes(), token.as_bytes())).map(|(user, _)| user))
    }

    // Creating

    /// Creates the bot's user (who, like anyone new, joins every open room after commit) and its
    /// `bots` row with a new token.
    pub fn create(tx: &mut Tx<'_>, attributes: NewBot) -> Result<(User, Bot)> {
        validate_name(&attributes.name)?;
        let user = User::create(
            tx,
            NewUser { name: attributes.name, password_digest: Some(attributes.password_digest), role: Role::Bot, ..NewUser::default() },
        )?;
        let now = tx.now();
        let token = generate_token();
        let id: i64 = tx.conn().query_row_cached(
            r#"INSERT INTO "bots" ("created_at", "creator_id", "token", "updated_at", "user_id") VALUES (?, ?, ?,",
  "output_tail": "

pub async fn edit(c: &mut Ctx) -> Result {
    concerns::before_actions(c, Before::default()).await?;
    let (user, _) = set_bot(c).await?;
    let form = BotForm { name: user.name.clone(), bot: Some(presenters::user_summary(&c.app().secrets, &user)), errors: Vec::new() };
    render_edit(c, StatusCode::OK, form).await
}

/// Renames the bot and replaces its avatar, then back to the list.
pub async fn update(c: &mut Ctx) -> Result {
    concerns::before_actions(c, Before::default()).await?;
    let (user, _) = set_bot(c).await?;
    let params = BotParams::from(c)?;
    let avatar = params.avatar.stage(c.app()).await?;
    let (name, form_user) = (params.name.clone(), user.clone());
    let saved = c
        .app()
        .db
        .write(move |tx| {
            let mut user = user;
            if let Some(name) = name {
                Bot::rename(&mut user, tx, name)?;
            }
            attachments::assign(tx, Record::user(user.id), "avatar", avatar)
        })
        .await;
    match saved {
        Ok(pending) => attachments::analyze_later(c.app(), pending),
        Err(campfire_db::Error::RecordInvalid(errors)) => {
            let bot = Some(presenters::user_summary(&c.app().secrets, &form_user));
            let form = BotForm { name: params.name.unwrap_or_default(), bot, errors: errors.full_messages() };
            return render_edit(c, StatusCode::UNPROCESSABLE_ENTITY, form).await;
        }
        Err(error) => return Err(db_error(error)),
    }
    redirect_to_bots(c)
}

/// Deletes the bot: its code stops working, and its messages stay.
pub async fn destroy(c: &mut Ctx) -> Result {
    concerns::before_actions(c, Before::default()).await?;
    let (user, bot) = set_bot(c).await?;
    c.app()
        .write(move |tx| {
            let mut user = user;
            bot.destroy(tx, &mut user)
        })
        .await?;
    redirect_to_bots(c)
}

// --- Before-actions and params --------------------------------------------------------------------

/// The bot `params[:bot_id] || params[:id]` names, among those the user can manage; 404 for any
/// other, so someone else's bots can't even be told apart from missing ones.
pub(crate) async fn set_bot(c: &Ctx) -> Result<(User, Bot)> {
    let user = concerns::require_current_user(c)?.clone();
    let id = c.param_str("bot_id").or_else(|| c.param_str("id")).and_then(integer_cast).ok_or(Error::NotFound)?;
    c.app().read(move |conn| Bot::find_manageable_by(conn, &user, id)).await
}

/// `params.require(:bot).permit(:name, :avatar)`
struct BotParams {
    /// `None` when the key wasn't given.
    name: Option<String>,
    /// Only an upload changes the avatar: the form has no way to remove one.
    avatar: Assignment,
}

impl BotParams {
    fn from(c: &Ctx) -> Result<Self> {
        let params = c.params.require("bot")?.permit(&permit_keys(&["name", "avatar"]));
        let name = string_attribute(&params, "name").map(Option::unwrap_or_default);
        let avatar = match Assignment::from_params(&params, "avatar")? {
            upload @ Assignment::Create(_) => upload,
            _ => Assignment::Unchanged,
        };
        Ok(Self { name, avatar })
    }
}

// --- Rendering ------------------------------------------------------------------------------------

async fn render_new(c: &mut Ctx, status: StatusCode, form: BotForm) -> Result {
    c.respond_to(&[&format::HTML])?;
    framed_page!(c, status, |ctx| views::New { ctx, form: form.clone() }).await
}

async fn render_edit(c: &mut Ctx, status: StatusCode, form: BotForm) -> Result {
    c.respond_to(&[&format::HTML])?;
    let bot_id = form.bot.as_ref().map_or(0, |bot| bot.id);
    framed_page!(c, status, |ctx| views::Edit { ctx, form: form.clone(), bot_id }).await
}

pub(crate) fn redirect_to_bots(c: &mut Ctx) -> Result {
    let location = c.url_for(&campfire_routes::bots());
    c.redirect_to(&location)
}

