    pub fn create(tx: &mut Tx<'_>, attributes: NewBot) -> Result<(User, Bot)> {
        validate_name(&attributes.name)?;
        let user = User::create(
            tx,
            NewUser { name: attributes.name, password_digest: Some(attributes.password_digest), role: Role::Bot, ..NewUser::default() },
        )?;
        let now = tx.now();
        let token = generate_token();
        let id: i64 = tx.conn().query_row_cached(
            r#"INSERT INTO "bots" ("created_at", "creator_id", "token", "updated_at", "user_id") VALUES (?, ?, ?, ?, ?) RETURNING "id""#,
            params![now, attributes.creator_id, token, now, user.id],
            |r| r.get(0),
        )?;
        let bot = Bot { id, user_id: user.id, creator_id: attributes.creator_id, token, created_at: now, updated_at: now };
        Ok((user, bot))
    }

    // Updating

    /// Renames the bot's user.
    pub fn rename(user: &mut User, tx: &mut Tx<'_>, name: String) -> Result<()> {
        validate_name(&name)?;
        user.update(tx, UserChanges { name: Some(name), ..UserChanges::default() })
    }

    /// A new token, so the old key stops working.
    pub fn reset_token(&mut self, tx: &mut Tx<'_>) -> Result<()> {
        self.token = generate_token();
        self.updated_at = tx.now();
        tx.conn().execute_cached(
            r#"UPDATE "bots" SET "token" = ?, "updated_at" = ? WHERE "bots"."id" = ?"#,
            params![self.token, self.updated_at, self.id],
        )?;
        Ok(())
    }

    /// Deletes the bot: its key goes, and its user is deactivated as a person removed from the
    /// account is, so its messages keep their author.
    pub fn destroy(&self, tx: &mut Tx<'_>, user: &mut User) -> Result<()> {
        tx.conn().execute_cached(r#"DELETE FROM "bots" WHERE "bots"."id" = ?"#, [self.id])?;
        user.deactivate(tx)
    }

    // Attributes

    /// A random password for [`NewBot::password_digest`], which nothing ever checks.
    pub fn unusable_password() -> String {
        sql::alphanumeric(32)
    }

    /// What authenticates the bot's requests: its user id and token, as Rails Campfire's
    /// `User#bot_key` has them.
    pub fn key(&self) -> String {
        format!("{}-{}", self.user_id, self.token)
    }
}

fn generate_token() -> String {
    sql::alphanumeric(TOKEN_LENGTH)
}

/// `validates :name, presence: true`
fn validate_name(name: &str) -> Result<()> {
    let mut errors = Errors::default();
    if name.trim().is_empty() {
        errors.add("name", "can't be blank");
    }
    errors.into_result()
}
//! `BotsController`: chat bots, which any member can set up (not in Rails Campfire). Members see
//! and manage the bots they created; administrators, everyone's. See `campfire_db::Bot` and
//! `messages::by_bots`, the API bots post through.

pub mod keys;

use campfire_db::{Bot, NewBot, PasswordDigest, User};
use campfire_kit::{Ctx, Error, Result, StatusCode, format, permit_keys};
use campfire_views::bots::{self as views, BotForm, BotSummary};
use ruby_compat::integer_cast;

use crate::app::{AppCtx, db_error};
use crate::concerns::{self, Before};
use crate::controllers::presenters::attachments::{self, Assignment, Record};
use crate::controllers::presenters::page::framed_page;
use crate::controllers::presenters::{self, accounts::string_attribute};

/// Every bot the user can manage, by name, on one page.
pub async fn index(c: &mut Ctx) -> Result {
    concerns::before_actions(c, Before::default()).await?;
    c.respond_to(&[&format::HTML])?;
    let user = concerns::require_current_user(c)?.clone();
    let bots = c.app().read(move |conn| Bot::manageable_by(conn, &user)).await?;
    let secrets = c.app().secrets.clone();
    let bots: Vec<BotSummary> =
        bots.iter().map(|(user, bot)| BotSummary { user: presenters::user_summary(&secrets, user), key: bot.key() }).collect();
    // Bot codes are credentials: the page that shows them is never stored, by a browser or a cache.
    c.no_store();
    framed_page!(c, StatusCode::OK, |ctx| views::Index { ctx, bots: bots.clone() }).await
}

pub async fn new(c: &mut Ctx) -> Result {
    concerns::before_actions(c, Before::default()).await?;
    render_new(c, StatusCode::OK, BotForm::default()).await
}

/// Creates the bot (which joins every open room), then back to the list with its code.
pub async fn create(c: &mut Ctx) -> Result {
    concerns::before_actions(c, Before::default()).await?;
    let creator_id = concerns::require_current_user(c)?.id;
    let params = BotParams::from(c)?;
    let password_digest = PasswordDigest::hash(Bot::unusable_password(), c.app().db.env().bcrypt_cost).await.map_err(Error::internal)?;
    let name = params.name.clone().unwrap_or_default();
    let avatar = params.avatar.stage(c.app()).await?;
    let saved = c
        .app()
        .db
        .write(move |tx| {
            let (user, _) = Bot::create(tx, NewBot { name, creator_id, password_digest })?;
            attachments::assign(tx, Record::user(user.id), "avatar", avatar)
        })
        .await;
    match saved {
        Ok(pending) => attachments::analyze_later(c.app(), pending),
        Err(campfire_db::Error::RecordInvalid(errors)) => {
            let form = BotForm { name: params.name.unwrap_or_default(), errors: errors.full_messages(), ..BotForm::default() };
            return render_new(c, StatusCode::UNPROCESSABLE_ENTITY, form).await;
        }
        Err(error) => return Err(db_error(error)),
    }
    redirect_to_bots(c)
}

pub async fn edit(c: &mut Ctx) -> Result {
    concerns::before_actions(c, Before::default()).await?;
    let (user, _) = set_bot(c).await?;
    let form = BotForm { name: user.name.clone(), bot: Some(presenters::user_summary(&c.app().secrets, &user)), errors: Vec::new() };
    render_edit(c, StatusCode::OK, form).await
