//! The schema exactly as `bin/rails db:prepare` creates it on a fresh database, and the
//! connection settings from Rails' `config/database.yml` plus the sqlite3 adapter's
//! `DEFAULT_PRAGMAS`.
//!
//! `schema.sql` is the `sqlite_master` of a database Rails Campfire created with
//! `db:prepare` (loading its `db/schema.rb`), minus the objects SQLite derives on its
//! own (FTS5 shadow tables, `sqlite_sequence`, autoindexes). A fresh `db:prepare` loads
//! `schema.rb`, so columns come out in alphabetical order; databases that were migrated keep
//! migration order. All queries in this crate name their columns, so both work: most read them
//! by name, and the hot models (`sql::columns!`) select a list of them and read by position in
//! that list, never by position over `*`.

use rails_compat::clock::Clock;
use rusqlite::{Connection, OptionalExtension, params};

use crate::error::{Error, Result};
use crate::time::Timestamp;

pub const SCHEMA_SQL: &str = include_str!("schema.sql");

/// Every migration in Rails Campfire's `db/migrate`, oldest first.
#[rustfmt::skip]
pub const MIGRATION_VERSIONS: &[&str] = &[
    "20231215043540",
    "20231220143106",
    "20240110071740",
    "20240115124901",
    "20240130213001",
    "20240131105830",
    "20250825100957",
    "20250825100958",
    "20250825100959",
    "20251126092013",
    "20251126115722",
    "20251126130131",
    "20251212154340",
];

/// SHA1 of Rails Campfire's `db/schema.rb`, which `db:schema:load` records in `ar_internal_metadata`.
pub const SCHEMA_SHA1: &str = "56f2410816dfccbc3343656a12b5f69ca1dee4d2";

/// Indexes and tables this app adds to the Rails schema, created on boot when missing (new and
/// existing databases alike). Additive only, so the database still works with the Rails image.
pub const ADDITIONS: &[&str] = &[
    // A room's messages are paged by `created_at` (`last_page`, `page_before`, `page_after`), and
    // with only `index_messages_on_room_id` every room page sorted the room's whole history:
    // 60 ms at 236k messages, against 0.02 ms with this index.
    r#"CREATE INDEX IF NOT EXISTS "index_messages_on_room_id_and_created_at" ON "messages" ("room_id", "created_at")"#,
    // Bots (`models::bot`), which Rails Campfire doesn't have: a bot is a `users` row with the
    // `bot` role, and this row holds who created it and its key's token. A table of its own
    // rather than columns on `users`, so creating it on every boot is idempotent, and the Rails
    // image, which doesn't know it, reads `users` as before.
    r#"CREATE TABLE IF NOT EXISTS "bots" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "user_id" integer NOT NULL, "creator_id" integer NOT NULL, "token" varchar NOT NULL, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL)"#,
    r#"CREATE UNIQUE INDEX IF NOT EXISTS "index_bots_on_user_id" ON "bots" ("user_id")"#,
    r#"CREATE INDEX IF NOT EXISTS "index_bots_on_creator_id" ON "bots" ("creator_id")"#,
];

/// `timeout: 5000` in `config/database.yml`.
pub const BUSY_TIMEOUT_MS: u64 = 5000;

/// Applies the per-connection settings Rails applies (`SQLite3Adapter#configure_connection`),
/// except `mmap_size`: every reader remaps a memory-mapped database after each commit.
pub fn configure_connection(conn: &Connection) -> Result<()> {
    conn.busy_timeout(std::time::Duration::from_millis(BUSY_TIMEOUT_MS))?;
    conn.pragma_update(None, "foreign_keys", true)?;
    conn.pragma_update(None, "journal_mode", "wal")?;
    conn.pragma_update(None, "synchronous", "normal")?;
    conn.pragma_update(None, "journal_size_limit", 67_108_864)?;
    conn.pragma_update(None, "cache_size", 2000)?;
    Ok(())
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Prepared {
    /// The database was empty; the schema was loaded.
    Loaded,
    /// The schema was already current.
    UpToDate,
}

