/// Everything that outlives a request. Cheap to share as [`App`].
pub struct AppState {
    pub config: Config,
    pub secrets: Arc<Secrets>,
    pub clock: SharedClock,
    pub db: Database,
    pub storage: Arc<Storage>,
    pub cable: Cable,
    pub broadcasts: channels::Broadcasts,
