#[tokio::test]
async fn a_mentioned_bot_hears_about_the_message_and_its_plain_text_answer_is_posted() {
    let server = FakeServer::start(vec![
        Route::new("POST", "*", "/hook", 200).header("Content-Type", "text/plain; charset=utf-8").body("Restarted <build> #12 & more"),
    ])
    .await;
    let app = TestApp::boot().await;
    let mut david = app.david();
    create_bot_with_webhook(&mut david, "Build Bot", &format!("http://{}/hook", server.addr)).await;
    let (bot, key) = bot_named(&app, "Build Bot").await;

    let posted = post_message(&mut david, HQ, &mentioning(&app, bot.id, "restart the build please")).await;
    assert_eq!(posted.status, StatusCode::OK, "{}", posted.text());
    let message = app.db().read(|conn| Message::last_page(conn, HQ)).await.unwrap().pop().unwrap();
    assert_eq!(message.creator_id, DAVID);

    let received = received(&server, 1).await;
    assert_eq!(received.len(), 1);
    let request = &received[0];
    assert_eq!((request.method.as_str(), request.target.as_str()), ("POST", "/hook"));
    assert_eq!(request.header("content-type"), Some("application/json"));
    let payload: serde_json::Value = serde_json::from_slice(&request.body).unwrap();
    assert_eq!(payload["event"], "mention");
    assert_eq!(payload["author"], serde_json::json!({ "id": DAVID, "name": "David" }));
    assert_eq!(payload["room"]["id"], HQ);
    assert_eq!(payload["room"]["name"], "HQ");
    assert_eq!(payload["room"]["reply_to"], format!("/rooms/{HQ}/{}/messages", key.key()));
    assert_eq!(payload["message"]["id"], message.id);
    assert_eq!(payload["message"]["body"]["text"], "restart the build please");
    let html = payload["message"]["body"]["html"].as_str().unwrap();
    assert!(html.contains("action-text-attachment") && html.contains("restart the build please"), "{html}");
    assert_eq!(payload["message"]["link"], format!("/rooms/{HQ}/@{}", message.id));

    let answer = message_by(&app, HQ, bot.id).await.expect("the bot's answer");
    let stored = rich_text_body(&app, answer.id).await;
    assert!(stored.contains("Restarted &lt;build&gt; #12 &amp; more"), "{stored}");

    // The reply_to URL works as the bot's own posting URL.
    assert_eq!(post_as_bot(&app, HQ, &key.key(), "Later").await.status, StatusCode::CREATED);
}

#[tokio::test]
async fn html_answers_are_posted_and_no_content_posts_nothing() {
    let server = FakeServer::start(vec![
        Route::new("POST", "*", "/html", 200).header("Content-Type", "text/html").body("<p>Build <strong>green</strong></p>"),
        Route::new("POST", "*", "/quiet", 204),
    ])
    .await;
    let app = TestApp::boot().await;
    let mut david = app.david();
    create_bot_with_webhook(&mut david, "Html Bot", &format!("http://{}/html", server.addr)).await;
    create_bot_with_webhook(&mut david, "Quiet Bot", &format!("http://{}/quiet", server.addr)).await;
    let (html_bot, _) = bot_named(&app, "Html Bot").await;
    let (quiet_bot, _) = bot_named(&app, "Quiet Bot").await;

    post_message(&mut david, HQ, &mentioning(&app, quiet_bot.id, "anything?")).await;
    assert_eq!(received(&server, 1).await.len(), 1);
    post_message(&mut david, HQ, &mentioning(&app, html_bot.id, "status")).await;
    let answer = message_by(&app, HQ, html_bot.id).await.expect("the HTML bot's answer");
    assert!(rich_text_body(&app, answer.id).await.contains("<strong>green</strong>"));
    let quiet_id = quiet_bot.id;
    assert!(app.db().read(move |conn| Message::by_creator(conn, quiet_id)).await.unwrap().is_empty(), "204 posts nothing");

    // Unmentioned bots hear nothing.
    post_message(&mut david, HQ, "<p>No bots here</p>").await;
    tokio::time::sleep(Duration::from_millis(200)).await;
    assert_eq!(server.received().len(), 2);
}

